css:
.card {
  display: flex;
  align-items: center;
  gap: 16px;
  max-width: 480px;
  padding: 16px;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
}

.thumb {
  flex-shrink: 0;
  width: 120px;
  height: 120px;
  border-radius: 6px;
  background: #fed7aa;
  object-fit: cover;
}

.body {
  flex: 1;
  min-width: 0;
}

.title,
.text {
  margin: 0;
}

.title {
  font-weight: 600;
}

.text {
  margin-top: 6px;
  color: #52525b;
}

@media (max-width: 520px) {
  .card {
    flex-direction: column;
    align-items: stretch;
  }
}
